{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "분석 결과가 캠페인의 구체적인 실행 결정으로 이어졌는지 검증한다. 먼저 연락할 거래처를 정한 결정과 그 근거가 된 분석 내용의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 휴면 거래처 재접촉 캠페인을 진행한 상황이다.",
          "task": "거래처 분석 내용을 바탕으로 우선 연락할 대상을 정해야 했다.",
          "action": "마지막 발주 품목과 시기에서 파악한 내용을 연락 대상 선정에 적용한 방식을 설명한다.",
          "result": "분석 내용에 따라 어떤 거래처를 먼저 연락 대상으로 정했는지 드러난다. 재주문 성과 자체는 필수 근거로 요구하지 않는다."
        },
        "expectedEvidence": [
          "먼저 연락할 거래처를 정할 때 근거로 삼은 구체적인 분석 내용",
          "해당 분석 내용이 재접촉 대상의 우선순위를 정하는 데 적합하다고 판단한 이유",
          "분석 내용에 따라 실제로 먼저 연락하기로 정한 대상의 특성"
        ]
      },
      "question": "오름퍼니처에서 휴면 거래처 재접촉 캠페인을 진행하셨던데요, 먼저 연락할 거래처를 정하는 데 근거로 삼은 분석 내용은 무엇이었어요?",
      "answerTip": "기억나는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "연락 대상 선정에 사용한 분석 내용을 구체적으로 제시한다.",
            "분석 내용이 우선 연락 대상의 특성으로 이어지는 논리를 명확히 설명한다.",
            "그 분석을 실제 대상 선정에 적용한 내용이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "분석 내용과 우선 연락 대상 사이의 연결은 확인된다.",
            "분석 내용의 구체성이나 해당 대상을 먼저 선택한 이유에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "어떤 분석 내용을 대상 선정에 사용했는지 확인하기 어렵다.",
            "연락한 순서나 재주문 성과만 제시하고 분석 결과와 대상 선정의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인 성과를 해석해 개선 내용을 보고할 수 있는지 검증한다. 광고 소재 변경에 대해 사장님께 전달한 설명에서 성과 결과와 개선 행동의 연결이 드러나는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고를 집행하고 결과를 사장님께 말로 설명한 상황이다.",
          "task": "광고 소재 변경의 의미를 관찰한 성과에 근거해 전달해야 했다.",
          "action": "소재별 반응이나 변경 전후 결과를 해석해 소재 변경을 설명한 내용을 제시한다.",
          "result": "사장님께 전달한 설명에서 무엇이 효과가 있었고 소재 변경과 어떤 관련이 있는지 드러난다. 서면 보고서 작성이나 상대방의 동의는 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "광고 소재 변경에 대해 사장님께 실제로 전달한 설명 내용",
          "그 설명을 뒷받침한 소재별 클릭이나 문의 DM 등 성과 비교 내용",
          "관찰한 성과를 소재 변경의 효과 또는 필요성과 연결한 해석"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 결과를 사장님께 말로 설명하셨다는데요, 그때 광고 소재 변경에 대해 사장님께 어떤 설명을 하셨어요?",
      "answerTip": "당시 대화를 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "사장님께 전달한 광고 소재 변경 관련 설명을 구체적으로 제시한다.",
            "소재별 반응이나 변경 전후 성과를 근거로 설명한 내용이 확인된다.",
            "성과 비교를 통해 무엇이 효과가 있었는지 해석하고 이를 소재 변경과 명확하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "소재 변경에 대해 전달한 내용과 이를 뒷받침하는 성과 근거가 일부 확인된다.",
            "성과 비교가 구체적이지 않거나 성과 해석과 소재 변경 사이의 연결이 충분히 설명되지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "사장님께 어떤 설명을 전달했는지 확인하기 어렵다.",
            "소재를 바꿨다는 사실이나 수치만 나열하고 그 결과가 소재 변경에 갖는 의미를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}
